import{_ as l,o as e,c as o,am as t}from"./chunks/framework.CiF4W93w.js";const d=JSON.parse('{"title":"为什么CMS垃圾回收器被废弃并移除","description":"","frontmatter":{"title":"为什么CMS垃圾回收器被废弃并移除","excerpt":"摘要","date":"2025-08-20 19:17:49","updated":"2025-08-20 19:17:49"},"headers":[],"relativePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/为什么CMS垃圾回收器被废弃并移除.md","filePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/为什么CMS垃圾回收器被废弃并移除.md","lastUpdated":null}'),r={name:"基础/多线程并发与JVM原理/JVM入门_基础概念/为什么CMS垃圾回收器被废弃并移除.md"};function i(n,a,s,u,c,h){return e(),o("div",null,[...a[0]||(a[0]=[t('<p>CMS(Concurrent Mark Sweep)作为一款曾经非常流行的低延迟垃圾回收器，在JDK 9中被标记为废弃，并在JDK 14中被正式移除。</p><p>这一决定有多方面的原因：</p><h2 id="cms的核心缺陷" tabindex="-1">CMS的核心缺陷 <a class="header-anchor" href="#cms的核心缺陷" aria-label="Permalink to &quot;CMS的核心缺陷&quot;">​</a></h2><h3 id="_1-内存碎片问题" tabindex="-1">1. 内存碎片问题 <a class="header-anchor" href="#_1-内存碎片问题" aria-label="Permalink to &quot;1. 内存碎片问题&quot;">​</a></h3><p>CMS采用标记-清除算法，而不是标记-整理或复制算法。这导致：</p><ul><li>长期运行后产生大量内存碎片</li><li>当碎片过多时，可能出现大对象分配失败的情况（即使总体上有足够的内存）</li><li>最终可能触发Full GC进行内存整理，造成长时间停顿，违背低延迟的设计目标</li></ul><p>CMS提供了<code>-XX:+UseCMSCompactAtFullCollection</code>和<code>-XX:CMSFullGCsBeforeCompaction</code>参数来控制碎片整理，但这些方法都需要在Full GC时执行，仍然会导致较长停顿。</p><h3 id="_2-并发失败风险" tabindex="-1">2. 并发失败风险 <a class="header-anchor" href="#_2-并发失败风险" aria-label="Permalink to &quot;2. 并发失败风险&quot;">​</a></h3><p>CMS的并发特性使其面临以下风险：</p><ul><li><strong>并发模式失败(Concurrent Mode Failure)</strong>：当并发收集过程中，老年代填满速度快于CMS收集速度时，会触发一次串行的Full GC</li><li><strong>晋升失败(Promotion Failed)</strong>：当Survivor区放不下，需要晋升到老年代时，如果老年代空间不足，也会触发Full GC</li></ul><p>这些情况下，CMS会退化为使用单线程的Serial Old收集器进行垃圾回收，导致极长的停顿时间，严重影响系统性能。</p><h3 id="_3-cpu资源敏感" tabindex="-1">3. CPU资源敏感 <a class="header-anchor" href="#_3-cpu资源敏感" aria-label="Permalink to &quot;3. CPU资源敏感&quot;">​</a></h3><p>CMS为了尽可能减少停顿，会与应用线程并发执行，这意味着：</p><ul><li>CMS默认会占用系统CPU资源的1/4（JDK 5）或1/(n+3)（JDK 6及以后，n为CPU核数）</li><li>在CPU核心较少的系统上，CMS会显著影响应用性能</li><li>对计算密集型应用，影响尤为明显</li></ul><h3 id="_4-浮动垃圾问题" tabindex="-1">4. 浮动垃圾问题 <a class="header-anchor" href="#_4-浮动垃圾问题" aria-label="Permalink to &quot;4. 浮动垃圾问题&quot;">​</a></h3><p>因为CMS在并发标记和并发清理阶段用户线程还在运行，这会导致：</p><ul><li>标记完成后又有新的垃圾产生，这部分被称为&quot;浮动垃圾&quot;</li><li>这些垃圾只能等到下一次GC才能被清理</li><li>CMS需要预留一部分老年代空间给用户线程使用</li></ul><h3 id="_5-算法复杂-代码维护成本高" tabindex="-1">5. 算法复杂，代码维护成本高 <a class="header-anchor" href="#_5-算法复杂-代码维护成本高" aria-label="Permalink to &quot;5. 算法复杂，代码维护成本高&quot;">​</a></h3><p>CMS实现非常复杂：</p><ul><li>有大量的并发处理代码</li><li>需要处理各种边缘情况和异常情况</li><li>代码维护难度大，bug修复成本高</li></ul><h2 id="g1对比cms的优势" tabindex="-1">G1对比CMS的优势 <a class="header-anchor" href="#g1对比cms的优势" aria-label="Permalink to &quot;G1对比CMS的优势&quot;">​</a></h2><p>HotSpot团队开发G1垃圾回收器的主要目标就是替代CMS。G1解决了CMS的许多问题：</p><ol><li><strong>空间整合能力</strong>：G1具有内存压缩能力，能有效避免内存碎片问题</li><li><strong>可预测的停顿模型</strong>：G1允许用户指定期望的停顿时间，并尽力满足</li><li><strong>更灵活的堆内存管理</strong>：使用Region概念代替固定的分代物理空间</li><li><strong>增量式垃圾回收</strong>：每次只处理一部分Region，避免全堆扫描</li></ol><h2 id="战略决策因素" tabindex="-1">战略决策因素 <a class="header-anchor" href="#战略决策因素" aria-label="Permalink to &quot;战略决策因素&quot;">​</a></h2><p>Oracle做出废弃CMS的决策还有一些战略层面的考虑：</p><ol><li><strong>维护成本</strong>：同时维护多种GC算法意味着更高的开发和测试成本</li><li><strong>资源聚焦</strong>：将资源集中在G1和ZGC等新一代收集器的开发上</li><li><strong>技术迭代</strong>：随着硬件发展（多核、大内存），新的GC算法能提供更好的性能</li><li><strong>统一路线</strong>：简化JVM配置选项，为用户提供更清晰的最佳实践</li></ol><h2 id="官方声明" tabindex="-1">官方声明 <a class="header-anchor" href="#官方声明" aria-label="Permalink to &quot;官方声明&quot;">​</a></h2><p>JEP 291（Deprecate the Concurrent Mark Sweep (CMS) Garbage Collector）中明确表示：</p><blockquote><p>&quot;CMS垃圾收集器已经过时了。G1收集器是一个功能齐全的收集器，旨在替代CMS，具有类似的并发收集目标，无需像CMS那样进行太多性能调优就能获得合理的行为。&quot;</p></blockquote><h2 id="迁移建议" tabindex="-1">迁移建议 <a class="header-anchor" href="#迁移建议" aria-label="Permalink to &quot;迁移建议&quot;">​</a></h2><p>对于原先使用CMS的系统，官方建议：</p><ul><li>短期：升级到G1收集器（<code>-XX:+UseG1GC</code>）</li><li>中长期：评估ZGC或Shenandoah等低延迟收集器是否更适合业务需求</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>CMS被废弃并最终移除，是JVM演进过程中的一个必然结果。虽然CMS在其时代是一个优秀的低延迟收集器，但随着G1和ZGC等更先进技术的出现，它的各种固有缺陷（内存碎片、并发失败风险、复杂的维护成本等）使其不再是最佳选择。Oracle的这一决定代表了垃圾回收技术向着更低延迟、更高吞吐量、更易使用的方向发展的趋势。</p>',34)])])}const p=l(r,[["render",i]]);export{d as __pageData,p as default};
